        if not all(1 <= num <= 9 for num in row):
            return False
        if len(set(row)) != 9:
            return False

    # Check columns
    for col in range(9):
        column = [grid[row][col] for row in range(9)]
        if not all(1 <= num <= 9 for num in column):
            return False
        if len(set(column)) != 9:
            return False

